                         rule=TransformError(),
                         message='Error transforming template: {}'.format(cause.message)
                     )
                 )
         except Exception as e:
             # Existing exception handling...
             LOGGER.debug('Error transforming template: %s', str(e))
             LOGGER.debug('Stack trace: %s', e, exc_info=True)
             matches.append(
                 Match.create(
                     filename=self._filename,
                     rule=TransformError(),
                     message='Error transforming template: {}'.format(str(e))
                 )
             )

         return matches
